  2	/**
  3	 * @package Application
  4	 * @subpackage Administration
  5	 */
  6	
  7	declare(strict_types=1);
  8	
  9	use Application\EventHandler\Eventables\EventableListener;
 10	use Application\Interfaces\Admin\AdminAreaInterface;
 11	use Application\Interfaces\Admin\AdminScreenInterface;
 12	use AppUtils\ClassHelper;
 13	use AppUtils\Interfaces\StringableInterface;
 14	use AppUtils\OutputBuffering;
 15	use UI\Page\Navigation\QuickNavigation;
 16	use function AppUtils\parseVariable;
 17	
 18	/**
 19	 * Base class for individual steps in a wizard. Based on the application
 20	 * skeleton for administration pages, this allows for easy form handling
 21	 * and the base structure handles all the data flow and necessary updates.
 22	 *
 23	 * @package Application
 24	 * @subpackage Administration
 25	 * @author Sebastian Mordziol <s.mordziol@mistralys.eu>
 26	 *
 27	 * @see Application_Admin_Wizard
 28	 */
 29	abstract class Application_Admin_Wizard_Step extends Application_Admin_Skeleton
 30	{
 31	    public const int ERROR_CANNOT_UPDATE_FROM_UNMONITORED_STEP = 558002;
 32	    public const int ERROR_UNHANDLED_STEP_UPDATE = 558003;
 33	    public const int ERROR_STEP_MUST_BE_COMPLETE_FOR_OPERATION = 558004;
 34	
 35	    protected Application_Interfaces_Admin_Wizardable $wizard;
 36	    protected int $number;
 37	    protected string $id;
 38	    protected string $instanceID;
 39	    protected bool $updateRequired = false;
 40	
 41	   /**
 42	    * @var array<string,mixed>
 43	    */
 44	    protected ?array $data = null;
 45	
 46	   /**
 47	    * @var string[]
 48	    */
 49	    protected array $monitoredSteps;
 50	
 51	   /**
 52	    * @param Application_Interfaces_Admin_Wizardable $wizard
 53	    * @param int $number
 54	    * @param array<string,mixed> $data
 55	    */
 56	    public function __construct(Application_Interfaces_Admin_Wizardable $wizard, int $number, array $data=array())
 57	    {
 58	        parent::__construct(Application_Driver::getInstance());
 59	
 60	        $this->wizard = $wizard;
 61	        $this->number = $number;
 62	        $this->data = array_merge($this->getDefaultData(), $data);
 63	        $this->instanceID = nextJSID();
 64	        $this->monitoredSteps = $this->getMonitoredSteps();
 65	        $this->id = ClassHelper::getClassTypeName($this);
 66	
 67	        $this->init();
 68	    }
 69	
 70	   /**
 71	    * Called when all steps in the wizard have been
 72	    * initialized, and before the step is processed.
 73	    * Use this to set up the step's environment.
 74	    */
 75	    abstract public function initDone() : void;
 76	
 77	   /**
 78	    * Called right after instantiation of the step class.
 79	    * Used to set up the base environment. Note: the wizard
 80	    * is not finished initializing at this point. Use the
 81	    * {@link preProcess()} method otherwise.
 82	    */
 83	    abstract protected function init() : void;
 84	
 85	   /**
 86	    * Called before the step is processed, used for
 87	    * any initialization routines the step may need.
 88	    * At this time, all steps in the wizard have been
 89	    * initialized and can be accessed.
 90	    */
 91	    abstract protected function preProcess() : void;
 92	
 93	    abstract public function getLabel() : string;
 94	
 95	    /**
 96	     * @return array<string,mixed>
 97	     */
 98	    abstract protected function getDefaultData() : array;
 99	
100	    abstract public function _process() : bool;

